def find(text, pat):
    """前缀哈希:O(n) 预处理前缀哈希与 BASE 幂,任意子串哈希 O(1) 取出;命中后逐字符校验。
    适合『同一文本、多次/多模式查询』的场景。"""
    n, m = len(text), len(pat)
    if m == 0:
        return 0
    if m > n:
        return -1
    MOD = (1 << 61) - 1
    BASE = 131
    power = [1] * (n + 1)                 # power[k] = BASE^k % MOD
    for k in range(1, n + 1):
        power[k] = power[k - 1] * BASE % MOD
    h = [0] * (n + 1)                     # h[i] = hash(text[:i])
    for i in range(1, n + 1):
        h[i] = (h[i - 1] * BASE + ord(text[i - 1])) % MOD
    hp = 0
    for ch in pat:
        hp = (hp * BASE + ord(ch)) % MOD
    def sub(l, r):                        # 子串 text[l:r) 的哈希,O(1)
        return (h[r] - h[l] * power[r - l]) % MOD
    for i in range(n - m + 1):
        if sub(i, i + m) == hp and text[i:i + m] == pat:
            return i
    return -1
